1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUM_BY_ITEM_TYPE = {
4	  sword: 100,
5	  amulet: 60,
6	  staff: 80,
7	  potion: 40,
8	  rune: 25,
9	  moonstone: 25,
10	} as const satisfies Record<string, number>;
11	
12	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
13	
14	const BLOCK_SIZE = 3;
15	
16	const BLOCK_BASE_PREMIUM = 60;
17	
18	const CURSE_SURCHARGE_RATE = 0.5;
19	
20	const HIGH_ENCHANTMENT_THRESHOLD = 5;
21	
22	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
23	
24	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
25	
26	const LOYALTY_YEARS_THRESHOLD = 2;
27	
28	const LOYALTY_DISCOUNT_RATE = 0.2;
29	
30	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
31	
32	export type ScenarioResult = { premium: number };
33	
34	export type ScenarioOutcome = { results: ScenarioResult[] };
35	
36	type Item = {
37	  type: InsurableItemType;
38	  cursed?: boolean;
39	  enchantment?: number;
40	};
41	
42	type Customer = { yearsWithMHPCO: number };
43	
44	type Scenario = { customer: Customer; steps: { items: Item[] }[] };
45	
46	// Amounts are rounded in the MHPCO's favour: premiums (charged to the
47	// customer) round up.
48	const roundPremiumInMHPCOsFavour = (amount: number): number =>
49	  Math.ceil(amount);
50	
51	const countByItemType = (items: Item[]): Map<InsurableItemType, number> => {
52	  const counts = new Map<InsurableItemType, number>();
53	
54	  for (const item of items) {
55	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
56	  }
57	
58	  return counts;
59	};
60	
61	// Exactly 3 alike components form a building block at a special base premium.
62	const basePremiumForAlikeItems = (
63	  type: InsurableItemType,
64	  count: number,
65	): number =>
66	  count === BLOCK_SIZE
67	    ? BLOCK_BASE_PREMIUM
68	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
69	
70	const basePremiumOf = (items: Item[]): number =>
71	  [...countByItemType(items)]
72	    .map(([type, count]) => basePremiumForAlikeItems(type, count))
73	    .reduce((total, premium) => total + premium, 0);
74	
75	const ownBasePremiumOf = (item: Item): number =>
76	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
77	
78	// Item-specific modifiers apply to the affected item's own base premium,
79	// not to the policy total.
80	type ItemModifier = { appliesTo: (item: Item) => boolean; rate: number };
81	
82	const CURSE_MODIFIER: ItemModifier = {
83	  appliesTo: (item) => item.cursed === true,
84	  rate: CURSE_SURCHARGE_RATE,
85	};
86	
87	const HIGH_ENCHANTMENT_MODIFIER: ItemModifier = {
88	  appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
89	  rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
90	};
91	
92	const ITEM_MODIFIERS: ItemModifier[] = [
93	  CURSE_MODIFIER,
94	  HIGH_ENCHANTMENT_MODIFIER,
95	];
96	
97	const itemSurchargeOf = (items: Item[], modifier: ItemModifier): number =>
98	  items
99	    .filter(modifier.appliesTo)
100	    .reduce((total, item) => total + ownBasePremiumOf(item) * modifier.rate, 0);
101	
102	// Item modifiers accumulate: an item matching several of them pays each
103	// surcharge on its own base premium.
104	const itemSurchargesOf = (items: Item[]): number =>
105	  ITEM_MODIFIERS.reduce(
106	    (total, modifier) => total + itemSurchargeOf(items, modifier),
107	    0,
108	  );
109	
110	// Policy-wide modifiers are computed from the policy base premium, so the
111	// first insurance surcharge is 10 % of the base — not of base plus curse.
112	// A modifier's rate is signed: surcharges are positive, discounts negative.
113	type PolicyContext = { customer: Customer; precedingQuotes: number };
114	
115	type PolicyModifier = {
116	  appliesTo: (context: PolicyContext) => boolean;
117	  rate: number;
118	};
119	
120	const FIRST_INSURANCE_MODIFIER: PolicyModifier = {
121	  appliesTo: () => true,
122	  rate: FIRST_INSURANCE_SURCHARGE_RATE,
123	};
124	
125	const LOYALTY_MODIFIER: PolicyModifier = {
126	  appliesTo: ({ customer }) =>
127	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
128	  rate: -LOYALTY_DISCOUNT_RATE,
129	};
130	
131	// Each item in a quote counts as a first insurance regardless of customer
132	// history, so this discount stacks with the first insurance surcharge.
133	const FOLLOW_UP_CONTRACT_MODIFIER: PolicyModifier = {
134	  appliesTo: ({ precedingQuotes }) => precedingQuotes >= 1,
135	  rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
136	};
137	
138	const POLICY_MODIFIERS: PolicyModifier[] = [
139	  FIRST_INSURANCE_MODIFIER,
140	  LOYALTY_MODIFIER,
141	  FOLLOW_UP_CONTRACT_MODIFIER,
142	];
143	
144	// Policy modifiers accumulate: each applicable one is computed on the same
145	// policy base premium, never compounded on top of another.
146	const policyAdjustmentOf = (
147	  basePremium: number,
148	  context: PolicyContext,
149	): number =>
150	  POLICY_MODIFIERS.filter((modifier) => modifier.appliesTo(context)).reduce(
151	    (total, modifier) => total + basePremium * modifier.rate,
152	    0,
153	  );
154	
155	const quotePremium = (items: Item[], context: PolicyContext): number => {
156	  const basePremium = basePremiumOf(items);
157	
158	  return roundPremiumInMHPCOsFavour(
159	    basePremium +
160	      itemSurchargesOf(items) +
161	      policyAdjustmentOf(basePremium, context) +
162	      PROCESSING_FEE,
163	  );
164	};
165	
166	export const runScenario = (scenario: unknown): ScenarioOutcome => {
167	  const { customer, steps } = scenario as Scenario;
168	
169	  const results = steps.map((step, precedingQuotes) => ({
170	    premium: quotePremium(step.items, { customer, precedingQuotes }),
171	  }));
172	
173	  return { results };
174	};
