// The follow-up discount applies "on each contract after their first", so the
// context counts preceding QUOTE steps — not preceding steps. The two coincide
// while quotes are the only kind of step; they will not once claims interleave.
export const runScenario = (scenario: unknown): ScenarioOutcome => {
  const { customer, steps } = scenario as Scenario;

  const results: ScenarioResult[] = [];
  let precedingQuotes = 0;

  for (const step of steps) {
    results.push({
      premium: quotePremium(step.items, { customer, precedingQuotes }),
    });
    precedingQuotes += 1;
  }

  return { results };
};

