// `precedingQuotes` is currently the step index. That is correct only because
// every step is a quote; when claim steps interleave, this must become a count
// of preceding QUOTE steps ("each contract after their first"), not of steps.
export const runScenario = (scenario: unknown): ScenarioOutcome => {
  const { customer, steps } = scenario as Scenario;

  const results = steps.map((step, precedingQuotes) => ({
    premium: quotePremium(step.items, { customer, precedingQuotes }),
  }));

  return { results };
};
